def make(dish):
    im=Image.open(ROOT/'sources'/(dish+'.jpg'))
    mask=Image.new('L',im.size,0)
    ImageDraw.Draw(mask).polygon([(round(x*im.width/100),round(y*im.height/100)) for x,y in POLYGONS[dish]],fill=255)
    folder=OUT/'masks';folder.mkdir(exist_ok=True)
    path=folder/(dish+'.png');mask.save(path)
    return path
if __name__=='__main__':
    for d in ['curry','tiramisu','pizza','sushi']:make(d)
